#include <bits/stdc++.h>
using namespace std;
long long evaluate(int c1,int c3,int n,const vector<long long> & P){
    int idx2=2*n-2*c3-c1;
    int idx3=2*n+c3-c1;
    return 2*P[c1]+P[idx2]+3*P[idx3];
}
void solve()
{
    int n;cin>>n;
    vector<long long >a(3*n);
    for(int i=0;i<3*n;i++)
    {
        cin>>a[i];
    }
    sort(a.rbegin(),a.rend());
    vector<long long>P(3*n+1,0);
    for(int i=0;i<3*n;i++)
    {
        P[i+1]=P[i]+a[i];
        
    }
    long long max_total_strength=0;
    for(int c3=0;c3<=n;c3++)
    {
        int low=0;
        int high=n-c3;
        while(high-low>=3)
        {
            int m1=low+(high-low)/3;
            int m2=high-(high-low)/3;
            if(evaluate(m1,c3,n,P)<evaluate(m2,c3,n,P))
            {
                low=m1;
            }
            else{
                high=m2;
            }
        }
        for(int c1=low;c1<=high;++c1)
        {
            max_total_strength=max(max_total_strength,evaluate(c1,c3,n,P));
            
        }
        
    }
    cout<<max_total_strength<<endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    cin>>t;
    while(t--)
    {
        solve();
        
    }
    return 0;
    

        

}
